<?php $layout='layouts.app'; ?>
<div style="display:flex;justify-content:space-between;align-items:center"><div><h1>Parent Notifications</h1><p class="muted"><?= (int)$unread ?> unread notification(s).</p></div><a class="btn btn-outline" href="/parent-portal">Parent Portal</a></div>
<div class="card" style="margin-top:var(--space-4)"><div class="card-body"><?php foreach($messages as $message): ?><div style="padding:var(--space-4) 0;border-bottom:1px solid var(--border)"><div style="display:flex;justify-content:space-between"><div><h2><?= e($message['title']) ?></h2><div class="muted"><?= e(ucfirst($message['type'])) ?> · <?= e((string)$message['published_at']) ?></div></div><div><?= $message['read_at']===null?'<span class="badge">Unread</span>':'<span class="muted">Read</span>' ?></div></div><div style="margin-top:var(--space-3)"><?= nl2br(e($message['body'])) ?></div><?php if($message['read_at']===null): ?><form method="POST" action="/parent-portal/notifications/<?= (int)$message['id'] ?>/read" style="margin-top:var(--space-3)"><?= csrf() ?><button class="btn btn-outline" type="submit">Mark as read</button></form><?php endif; ?></div><?php endforeach; if(!$messages): ?><p>No notifications yet.</p><?php endif; ?></div></div>
